	[Serializable]
	public class CumToleranceEntry
	{
		private double fromHour;

		private object data;

		public CumToleranceEntry(double _from  )
		{
			fromHour = _from;

		}

		public double From
		{
			get
			{
				return this.fromHour;
			}
			set
			{
				this.fromHour = value;
			}
		}


		public bool Qualifies( double minutesBehind )
		{
			double minsValFrom = this.fromHour * 60;
			//double minsValTo  = this.toHour * 60;

			if (  minutesBehind >= minsValFrom  )
			{
				return true;

			}
			else
			{
				return false;
			}
		}

		public object Data
		{
			get
			{
				return this.data;
			}
			set
			{
				this.data = value;
			}
		}
	}

