	[Serializable]
	public class WorkingPitch : AbstractPitchDetail
	{
		public WorkingPitch(ng.data.requirements.heijunka.AbstractPitchDetail apd)
		{
			this.DataIndicator   = apd.DataIndicator;
			this.DivisionIntCode = apd.DivisionIntCode;
			this.DivisionName    = apd.DivisionName;
			this.EnterpriseName  = apd.EnterpriseName;
			this.InstanceName    = apd.InstanceName;
			this.LineID          = apd.LineID;
			this.LineIntCode     = apd.LineIntCode;
			this.Replan          = apd.Replan;
			this.ShiftStartDate  = apd.ShiftStartDate;
			this.ShiftEndDate    = apd.ShiftEndDate;
			this.PitchStartDate  = apd.PitchStartDate;
			this.PitchEndDate    = apd.PitchEndDate;
			this.PitchNbr        = apd.PitchNbr;
			this.PitchType       = apd.PitchType;
		}
		public WorkingPitch()
		{
		}

		public bool PitchInterval(ng.data.requirements.heijunka.AbstractPitchDetail apd,System.TimeSpan _Time)
		{
			System.TimeSpan timeSpan;
			timeSpan = (apd.PitchStartDate - apd.PitchEndDate);
			if (timeSpan == _Time)
			{
				return true;
			}
			return false;
		}

		public void Save()
		{
			System.Text.StringBuilder sb = new System.Text.StringBuilder();

			string startTimeStr = ng.utils.DbTypeResolver.DbStringBuilder.DateValue(this.PitchStartDate).ToString();
			string endTimeStr = ng.utils.DbTypeResolver.DbStringBuilder.DateValue(this.PitchEndDate).ToString();

//			sb.Append("INSERT INTO HEIJUNKA_PITCH_SCHEDULE( ");
//			sb.Append(" DATA_INDICATOR, RE_PLAN, ENTERPRISE_NAME,DIVISION_NAME, ");
//			sb.Append(" INSTANCE_NAME, LINE_ID, SHIFT_NAME, SHIFT_START_DT, SHIFT_END_DT, PITCH_NBR, ");
//			sb.Append(" PITCH_START_DT, PITCH_END_DT, NON_WORKING_DESC, NON_WORKING_START_DT, NON_WORKING_END_DT, ");
//			sb.Append(" DIVISION_INT_CODE, SITE_INT_CODE, LINE_INT_CODE,ROW_ID, IN_USE, PITCH_ITEM_ID, CUM_COUNT, PITCH_TYPE) ");
//			sb.Append("VALUES('" + this.DataIndicator + "', NULL , '" + this.EnterpriseName + "', '" + this.DivisionName + "', ");
//			sb.Append("'" + this.InstanceName + "', '" + this.LineID + "', '" + this.ShiftName + "', " + startTimeStr + ", " + endTimeStr + ", ");
//			sb.Append(" " + this.PitchNbr + ", " +  startTimeStr + ", " + endTimeStr + ", ");
//			sb.Append(" NULL, NULL, NULL, ");
//			sb.Append(" '" + this.DivisionIntCode + "', '" + this.SiteIntCode + "', '" + this.LineIntCode + "', " + this.Row_ID + ", 'N' , NULL , " + this.CumCount + ", ");
//
//			sb.Append(" '" + this.PitchType.ToString().ToUpper() + "'");
//
//			
//			sb.Append(")");

			ng.utils.sql.SqlSaveBuilder oIns = new ng.utils.sql.SqlSaveBuilder();
			oIns.addColumn("DATA_INDICATOR",this.DataIndicator.ToString());
			oIns.addColumn("RE_PLAN",ng.utils.DbTypeResolver.DbStringBuilder.DbNullVal());
			oIns.addColumn("ENTERPRISE_NAME",this.EnterpriseName.ToString());
			oIns.addColumn("DIVISION_NAME",this.DivisionName.ToString());
			oIns.addColumn("INSTANCE_NAME",this.InstanceName.ToString());
			oIns.addColumn("LINE_ID",this.LineID.ToString());
			//oIns.addColumn("SHIFT_NAME",this.ShiftName.ToString());
			oIns.addColumn("SHIFT_NAME",this.ShiftName);
			oIns.addColumn("SHIFT_START_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(startTimeStr));
			oIns.addColumn("SHIFT_END_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(endTimeStr));
			oIns.addColumn("PITCH_NBR",this.PitchNbr);
			oIns.addColumn("PITCH_START_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(startTimeStr));
			oIns.addColumn("PITCH_END_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(endTimeStr));
			oIns.addColumn("NON_WORKING_DESC",ng.utils.DbTypeResolver.DbStringBuilder.DbNullVal());
			oIns.addColumn("NON_WORKING_START_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbNullVal());
			oIns.addColumn("NON_WORKING_END_DT",ng.utils.DbTypeResolver.DbStringBuilder.DbNullVal());
			oIns.addColumn("DIVISION_INT_CODE",this.DivisionIntCode.ToString());
			//oIns.addColumn("SITE_INT_CODE",this.SiteIntCode.ToString());
			oIns.addColumn("SITE_INT_CODE",this.SiteIntCode);
			//oIns.addColumn("LINE_INT_CODE",this.LineIntCode.ToString());
			oIns.addColumn("LINE_INT_CODE",this.LineIntCode);
			oIns.addColumn("ROW_ID",this.Row_ID);
			oIns.addColumn("IN_USE","N");
			oIns.addColumn("PITCH_ITEM_ID",ng.utils.DbTypeResolver.DbStringBuilder.DbNullVal());
			oIns.addColumn("CUM_COUNT",this.CumCount);
			oIns.addColumn("PITCH_TYPE",this.PitchType.ToString().ToUpper());

			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
			{
				conn.Open();
				System.Data.IDbCommand cmd = conn.CreateCommand();
				//cmd.CommandText = sb.ToString();
				cmd.CommandText = oIns.formatInsert("HEIJUNKA_PITCH_SCHEDULE");
				int rows = cmd.ExecuteNonQuery();
				conn.Close();
			}


		}


	}

