	[Serializable]
	public class ServerPitch
	{


		protected static  bool hasStarted = false;
		protected System.Collections.IList m_aLinePitch = new ArrayList();


		public static bool HasStarted
		{
			get
			{
				return ServerPitch.hasStarted;
			}
		}


		public System.Collections.IList Lines
		{
			get
			{
				return m_aLinePitch;
			}
		}

		public void KillAll()
		{
			foreach (LinePitch lp in m_aLinePitch)
			{
				ng.utils.ThreadUtils.StopThread(lp.Thread);
			}
		}


		public void Add(ng.data.requirements.heijunka.LinePitch lP)
		{
			m_aLinePitch.Add(lP);
		}

		public void Add(ng.data.requirements.heijunka.Pitch pitch)
		{

		}



		public ng.data.requirements.heijunka.LinePitch GetLinePitch(ng.data.requirements.heijunka.AbstractPitchDetail ap)
		{
			foreach(ng.data.requirements.heijunka.LinePitch lp in this.Lines)
			{
				if (lp.LineID == ap.LineID)
				{
					return lp;	
				}
			}

			return null;
		}

		public ng.data.requirements.heijunka.LinePitch GetLinePitch(string lineID)
		{
			foreach(ng.data.requirements.heijunka.LinePitch lp in this.Lines)
			{
				if (lp.LineID == lineID)
				{
					return lp;	
				}
			}

			return null;
		}




		public void Start()
		{
			// implement start method

			ServerPitch.hasStarted = true;

			this.CreateLinePitch();

			foreach( LinePitch lp in this.m_aLinePitch )
			{
				lp.Start();
			}
		}

		public  ng.data.requirements.heijunka.LinePitch CreateLinePitch( ng.data.Line line )
		{
			ng.data.requirements.heijunka.HeijunkaManager hm = ng.data.requirements.heijunka.HeijunkaManager.getInstance();

			ng.data.requirements.heijunka.LinePitch lp = new ng.data.requirements.heijunka.LinePitch(this,line);


			// register to events
			lp.LinePitchEvent += new LinePitchDelegate( hm.OnLinePitch );
			lp.LinePitchItemEvent += new LinePitchItemDelegate( hm.OnLinePitchItem );				
			this.m_aLinePitch.Add( lp );

			return lp;



		}
		protected void CreateLinePitch()
		{
			//ng.data.requirements.heijunka.HeijunkaManager hm = ng.data.requirements.heijunka.HeijunkaManager.getInstance();

			foreach (ng.data.Line line in ng.data.requirements.heijunka.HeijunkaManager.getInstance().ListOfSupportedLines)
			{
				//ng.data.requirements.heijunka.LinePitch lp = new ng.data.requirements.heijunka.LinePitch(this,line);

				this.CreateLinePitch( line );

//				// register to events
//				lp.LinePitchEvent += new LinePitchDelegate( hm.OnLinePitch );
//				lp.LinePitchItemEvent += new LinePitchItemDelegate( hm.OnLinePitchItem );				
//				this.m_aLinePitch.Add( lp );




			}
		}

		public string GetReport()
		{

			System.Text.StringBuilder sb = new System.Text.StringBuilder();

			sb.Append("DayPitch\r\n");
			foreach( LinePitch lp in this.Lines )
			{
				lp.GetReport(sb);

			}

			return sb.ToString();

		}
	}

