		public void LoadProductionSchedule()
		{

			int oldCount=0;
			if ( this.hps != null )
			{
				oldCount = hps.Requirements.Count;
			}


			if ( hps == null )
			{
				hps = new HeijunkaProductionSchedule( this.line );
			}

			lock( hps.SyncRoot )
			{
				hps.LinePitch = this;
				ng.utils.logging.LogWriter.writeLine("Loading Production Schedule......");
				hps.LoadAllItems();

