				// get the forecasted parts per pitch
				ng.data.requirements.heijunka.HeijunkaForecast hjf = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetForecast( this.LineID );

				if ( hjf != null )
				{
					ng.data.requirements.heijunka.HeijunkaForecastEntry fce  = hjf.GetForecastEntry( System.DateTime.Now );
					if ( fce != null )
					{
						Pitch p = null;
						//int critCount = fce.PartsPerPitch * 2;
						double critCount = fce.PartsPerPitch * 2;

						if ( this.currentPitch == null )
						{
							if ( this.lastPitchCompleted != null )
							{
								p = this.lastPitchCompleted;
							}
							else
							{
								// no current pitch, no prior pitch must mean no pitch has ever ran so you are not 
								// in trouble,
								return false;
							}
						}
						else
						{
							p = this.currentPitch;
						}

						if ( -p.CumCount >= critCount )
						{
							return true;
						}
						else
						{
							return false;
						}
					}
				}

				// returning true because if this happens it means we have no forecast.  That's F'd up and
				// we should be alerted.
				return true;


			}
		}
		internal bool SleepForPitch( System.TimeSpan ts )
		{
			System.DateTime targetDate = System.DateTime.Now.Add( ts );

			try
			{
				//System.Threading.Thread.Sleep( ts );
				while( true )
				{


					System.DateTime currentDate = System.DateTime.Now;

					System.TimeSpan diff = targetDate - currentDate;


					if ( diff.TotalMinutes < 0 )
					{
						return true;   // means overdue
					}
					else if ( diff.TotalMinutes < ((double)1.0) )
					{
						System.Threading.Thread.Sleep( diff );  //sleep less than a minute
					}
					else
					{
						System.Threading.Thread.Sleep( 60 * 1000 );  //sleep for a minute
					}
					if ( System.DateTime.Now >= targetDate )
					{
						return true;
					}
				}

			}
			catch( System.Threading.ThreadInterruptedException )
			{
				return false;
			}
			catch( System.Threading.ThreadAbortException )
			{
				return false;
			}
		}

		public void Kill()
		{
			try
			{
				if ( this.thread != null )
				{
					this.thread.Abort();
				}
			}
			catch( System.Exception e)
			{
				ng.utils.logging.LogWriter.writeLine( e );
			}
		}
		public void Wakeup(bool replan)
		{
			while ( ( System.Threading.ThreadState.SuspendRequested & this.Thread.ThreadState) == System.Threading.ThreadState.SuspendRequested )
			{
				System.Threading.Thread.Sleep( 200 );
			}

			if ( ( System.Threading.ThreadState.Suspended & this.Thread.ThreadState) == System.Threading.ThreadState.Suspended)
			{
				this.Thread.Resume();
			}


			if (this.currentPitch == null )
			{
				if ( (System.Threading.ThreadState.WaitSleepJoin & this.Thread.ThreadState )== System.Threading.ThreadState.WaitSleepJoin )
				{
					try
					{
						ng.utils.logging.LogWriter.writeLine("Interrupting Line Pitch");
						this.thread.Interrupt();
					}
					catch( System.Exception e )
					{
						ng.utils.logging.LogWriter.writeLine("Interrupting Line Pitch Exception: "+ e);
					}
				}
			}




		}

		public double GetMinutesBehind( Pitch fromPitch )
		{
			if ( fromPitch != null )
			{
				double minPerPart = this.MinutesPerPart;

				if ( minPerPart > 0 )
				{

					double partsBehind = 0;

					if ( fromPitch.PitchStartDate > System.DateTime.Now )
					{
						partsBehind = this.GetCumCountFromStats(null);
					}
					else
					{
						partsBehind = fromPitch.CumCount;
					}

					// only do this if the current pitch is a NORMAL pitch
					double elapsed = 0;

					if  ( fromPitch.PitchType == PitchType.NORMAL )
					{
						// get minutes elapsed
						elapsed = fromPitch.WorkTimeElapsed.Minutes;
					}

					// get currently packed qty.
					double packedQty = 0;

					if ( fromPitch.PitchJob != null )
					{
						packedQty = fromPitch.PitchJob.Quantity;
					}

					// calculate what the elapsed time is based on actual packqty using the MinutesPerPart
					double timeCalc = packedQty * minPerPart;
					double minsBehind = elapsed - timeCalc;


					// If we have a negative cum then we are behind if not we are not, quite simple.
					if ( partsBehind < 0 )
					{
						double absVal = System.Math.Abs( partsBehind );
						//double absVal = partsBehind;

						minsBehind = minsBehind + (minPerPart * absVal);
					}

					//return System.Math.Ceiling( minsBehind );
					return minsBehind;
				}
			}

			return 0;

		}

		public double MinutesBehind
		{
			get
			{
				return this.GetMinutesBehind( this.CurrentPitch );

			}
		}


