				//string sql = "SELECT SHIFT_START_DT , SHIFT_END_DT FROM HEIJUNKA_PITCH_SCHEDULE WHERE LINE_ID = '" + this.LineID + "' " + 
				//	" AND ROW_ID = " + currentRow;

				using ( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
				{
					conn.Open();
					System.Data.IDbCommand cmd = conn.CreateCommand();
					cmd.CommandText = sql;

					System.Data.IDataReader rdr = cmd.ExecuteReader();
					bool fallsBetween = false;

					try
					{
						if ( rdr.Read() ) 
						{
							System.DateTime dtStart = (System.DateTime) rdr.GetDateTime( rdr.GetOrdinal("SHIFT_START_DT") );
							System.DateTime dtEnd = (System.DateTime) rdr.GetDateTime( rdr.GetOrdinal("SHIFT_END_DT") );

							if ( _dateTime >= dtStart  && _dateTime <= dtEnd )
							{
								fallsBetween = true;
							}

						}

						return fallsBetween;

					}
					finally
					{
						rdr.Close();
						conn.Close();
					}
				}
			}
			else
			{
				return false;
			}
		}
