		public int GetCumCountFromStats(ng.data.requirements.heijunka.Pitch _currentPitch)
		{
			// 10/27/2003 -- RB
			//string sql = "SELECT CURRENT_PITCH_ROW FROM HEIJUNKA_LINE_STATS WHERE LINE_ID = '" + this.LineID + "'";

			ng.utils.SelectStatement select = new ng.utils.SelectStatement();
			select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_LINE_STATS"));
			select.Columns = "CURRENT_PITCH_ROW";
			select.Where = "LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.LineID );
			string sql = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);

			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
			{
				conn.Open();
				System.Data.IDbCommand cmd = conn.CreateCommand();
				cmd.CommandText = sql;

				System.Data.IDataReader pitchRdr = null;

				int cumCount = 0;

				//double cumCount = 0;

				System.Data.IDataReader rdr = cmd.ExecuteReader();
				try
				{
					if ( rdr.Read() )
					{


						long pitchRow = Convert.ToInt64(rdr["CURRENT_PITCH_ROW"]);
						rdr.Close();

						// now get pitch row.
						// 10/27/2003 -- RB
						//string pitchSQL = "SELECT PITCH_ITEM_ID, CUM_COUNT FROM HEIJUNKA_PITCH_SCHEDULE WHERE ROW_ID = " + pitchRow;

						select = new ng.utils.SelectStatement();
						select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_PITCH_SCHEDULE"));
						select.Columns = "PITCH_ITEM_ID, CUM_COUNT";
						select.Where = "ROW_ID = " + pitchRow;
						string pitchSQL = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);

						System.Data.IDbCommand cmdPitch = conn.CreateCommand();
						cmdPitch.CommandText =  pitchSQL;
						pitchRdr = cmdPitch.ExecuteReader();


						try 
						{
							if ( pitchRdr.Read() )
							{
								// get
								string pitchItem = null;


								if ( pitchRdr.IsDBNull( 1 ) == false )
								{
									cumCount = Convert.ToInt32(pitchRdr["CUM_COUNT"]);
								}

								if ( pitchRdr.IsDBNull(  0 ) == false )
								{
									pitchItem = (string) pitchRdr["PITCH_ITEM_ID"];
								}

								pitchRdr.Close();


								try
								{
									if ( pitchItem != null  )
									{
										bool checkPitchJob = true;

										if ( _currentPitch != null && _currentPitch.PitchJob != null )
										{
											if( _currentPitch.PitchJob.ID == pitchItem )
											{
												checkPitchJob = false;
											}
										}


										if ( checkPitchJob )
										{
											ng.data.requirements.JobItem pitchJob = new ng.data.requirements.JobItem(pitchItem);

											if ( _currentPitch != null )
											{

												if ( _currentPitch.PitchJob != null && pitchJob.ID != _currentPitch.PitchJob.ID )
												{
													// this means that _currentPitch is more current we need to count
													// how many items we created under the pitchJob.
													int pitchItems = pitchJob.GetMarriedCount();

													int diff = pitchItems - _currentPitch.PartsPerPitch;
													cumCount = cumCount + diff;
												}
											}
											// now that we have the PitchJob we need to see how many 
										}

									}
								}
								catch( ng.data.exceptions.ObjectNotFoundException )
								{
									// no PitchJob, this means that no items were packed under this pitch
									// Determine if the current Pitch and the stats pitch row are the same.

									if ( _currentPitch.RowID == pitchRow )
									{
										// ok, no problem this means that the pitchRow is pointing to _currentPitch
										// just return the cumCount and be done
									}
									else
									{

									}
								}



							}
						}
						finally 
						{
							pitchRdr.Close();
						}
					}
					else
					{
						rdr.Close();
						if ( _currentPitch != null )
						{
							cumCount = (int)_currentPitch.CumCount;
						}
						// no row for line.
					}
				}
				finally
				{

					if ( rdr != null && rdr.IsClosed == false )
					{
						rdr.Close();
					}
					if ( pitchRdr != null && pitchRdr.IsClosed == false )
					{
						pitchRdr.Close();
					}
				}


				return cumCount;
			}


		}


