		private void MoveShiftToHistory( ShiftPitch sp )
		{

			// null shift name indicates an extended shift.

			if ( this.previousShifts == null )
			{
				this.previousShifts = new System.Collections.ArrayList();
			}


			lock( this.previousShifts.SyncRoot )
			{
				if  (this.previousShifts.Count > 0 )
				{
					System.Collections.ArrayList copyPL = new System.Collections.ArrayList( this.previousShifts );
					foreach( ShiftPitch pSp in copyPL )
					{
						System.TimeSpan diff = System.DateTime.Now.Subtract( pSp.ShiftStartDate );

						if ( diff.TotalHours > 24 )
						{
							pSp.Clear();
							this.previousShifts.Remove( pSp );

						}
					}

				}

				//add shift
				lock ( this.m_aShiftPitch.SyncRoot )
				{
					this.m_aShiftPitch.Remove( sp );
					this.previousShifts.Add( sp );
				}


				// purge old data
				this.PurgeData( 7 );

			}
		}

