		/// <summary>
		/// This method will extend the total Order qty (via the Pitch.OverPlan qty) if we are behind a certain
		/// number of hours.  Overplan rules are graduated, this means that rules are enforced collectively 
		/// as the Minutes behind increases.  This means that the 1 hour behind rule will be enforced along with the
		/// 8 hours behind rule.
		/// </summary>
		/// <param name="_currentPitch"></param>
		/// 
		protected void SetOverPlan(Pitch _currentPitch)
		{
			ng.data.requirements.heijunka.HeijunkaLineSetupOptions hls = this.GetLineOptions();

			if ( hls != null )
			{

				// enforce the simple over plan tolerance
				if ( hls.OverPlanTolerance != null )
				{


					if ( _currentPitch.CumCount < 0 && hls.OverPlanTolerance.Qualifies( this.MinutesBehind ) )
					{
						int basePPP = _currentPitch.PartsPerPitch;
						int extendBaseQty = _currentPitch.PartsPerPitch;
						// if the current pitch type is extended shift then enforce 2 * PPP
						if ( hls.ExtendedShiftTolerance.Qualifies( this.MinutesBehind ) && _currentPitch.PitchType != PitchType.NORMAL )
						{
							//							extendBaseQty = this.PartsPerPitch * 2; 
							//							basePPP = this.PartsPerPitch;



						}


						double d_rate = (double) hls.OverPlanTolerance.Data + (double) 1.0;

						int overPlan = (int)System.Math.Ceiling(( extendBaseQty * d_rate));

						_currentPitch.OverPlanQty = overPlan - basePPP;

						ng.utils.logging.LogWriter.writeLine("Setting overplan qty for Pitch to " + _currentPitch.OverPlanQty);

					}
				}






			}

		}

		public void OnPitch( Pitch p , string mode )
		{
			if ( mode.ToUpper() == "BEGIN" )
			{

				this.currentPitch = p;

				ng.data.requirements.heijunka.HeijunkaForecast hjf = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetForecast( this.LineID );
				ng.data.requirements.heijunka.HeijunkaForecastEntry fce  = hjf.GetForecastEntry( System.DateTime.Now );

				if ( fce != null )
				{
					this.SetPartsPerPitch( p , fce );
				}
				//this.currentPitch.PartsPerPitch = this.PartsPerPitch;

				// get cum from last pitch
				int prevCum = this.GetCumCountFromStats( p );

				p.CumCount = prevCum;

				if ( p.ResetCum )
				{
					// this means that we need to Reset the Production Schedule
					this.ProductionSchedule.HandleReplan( p ); 

					p.CumCount = 0;
				}

				this.UpdateStats();    

				// enforce behind logic for pitches only.  Shift and Overtime logic is placed at the end of shifts in the
				// Run() method

				// This may extend the total to be built qty.
				this.SetOverPlan( p );

				// Update listeners
				DispatchCurrentIndex();
				DispatchStats();

				if ( this.LinePitchEvent != null )
				{
					this.LinePitchEvent( this , p, mode );
				}
			}
			else
			{

				lastPitchCompleted = p;

				// lock to prevent a clash of data being received and a pitch ending
				lock(ng.data.requirements.heijunka.HeijunkaManager.getInstance().SyncRoot)
				{
					if ( this.LinePitchEvent != null )
					{
						this.LinePitchEvent( this , p, mode );
					}

					// pitch ending, get cum value of the ending cum.
					// then get current packed qty.
					double prevCum = this.currentPitch.CumCount;

					double currPack = 0;
					if ( this.currentPitch.PitchJob != null )
					{
						currPack = this.currentPitch.PitchJob.GetMarriedCount();  // getting from DB
					}

					// if pitchCum is greater than zero than we made up some ground.
					// If it is negative our next pitch will have a cum of prevCum + pitchCum
					// Only subtract the PartsPerPitch qty if the Pitch Type is NORMAL

					int ppp = 0;
					//double ppp = 0;

					if (this.currentPitch.PitchType == PitchType.NORMAL )
					{
						ppp = this.currentPitch.PartsPerPitch;
//						double x=550;
//						double y=18;
//						ppp = (x/y);
					}

					double pitchCum = currPack - ppp;

					if ( this.currentPitch.PitchType == PitchType.NORMAL )
					{
						this.currentPitch.SetCumOffsetStatistics( (int)pitchCum );
					}

					double newCum = prevCum + pitchCum;
					this.currentPitch.CumCount = newCum;
					this.currentPitch.UpdatePitch();

				}
				// Fire events
				DispatchPitch(currentPitch);

				//ng.data.requirements.heijunka.Pitch nextPitch = this.GetNextPitch( this.currentPitch );



			}


		}

