		private void Run()
		{

			// have to have a looping mechanism

			//			lock ( ng.data.requirements.heijunka.HeijunkaManager.getInstance().SyncRoot )
			//			{
			//				if (ng.data.requirements.heijunka.HeijunkaManager.getInstance().MonitoringFiles == false  )
			//				{
			////					this.LoadProductionSchedule();
			//				}
			//			}

			//this.LoadProductionSchedule();
			if ( this.hps != null )
			{
				//bool gotPitches = false;
				//while( gotPitches == false )
				//{
				// load ALL new and inuse pitches when first starting.
				try
				{
					ng.utils.logging.LogWriter.writeLine("Starting PitchLine for Line: " + this.LineID );
					this.Load(false,null);
					ng.utils.logging.LogWriter.writeLine("Finished Loading Pitch data: " + this.LineID );
					//	gotPitches = true;
				}
				catch ( ng.data.requirements.heijunka.PitchDataNeedsReloadingException )
				{
					ng.utils.logging.LogWriter.writeLine("Pitch Data needs to be reloaded and prepared: " + this.LineID);
				}
				catch( ng.data.exceptions.ObjectNotFoundException  )
				{
					ng.utils.logging.LogWriter.writeLine("No Pitch Data for today:  will try again later: " + this.LineID);
					//						try
					//						{
					//							//this.thread.Suspend();
					//						}
					//						catch( System.Threading.ThreadAbortException )
					//						{
					//							// shutdown linePitch
					//							return;
					//						}
					//						catch( System.Threading.ThreadInterruptedException )
					//						{
					//							// shutdown linePitch
					//						}
					//						catch( System.Exception )
					//						{
					//						}
				}
				//}
			}


			bool loadPS = false;
			while( true )
			{


				try
				{

					// verify that we have a production schedule
					while(true)
					{


						if ( this.hps != null )
						{
							ng.utils.logging.LogWriter.writeLine("Check Production Schedule Requirements Count: " + this.LineID );

							if ( this.hps.Requirements.Count == 0 )
							{
								loadPS = true;
							}
						}
						else
						{
							loadPS = true;
						}

						if ( loadPS )
						{
							loadPS = false; // reset

							lock ( ng.data.requirements.heijunka.HeijunkaManager.getInstance().SyncRoot )
							{
								if (ng.data.requirements.heijunka.HeijunkaManager.getInstance().MonitoringFiles == false  )
								{
									//this.LoadProductionSchedule();
								}
							}

							if ( this.hps.Requirements.Count == 0 )
							{
								try
								{
									ng.utils.logging.LogWriter.writeLine("No KANBAN data will try again later: " + this.LineID);
									System.Threading.Thread.Sleep( 1 * ( 1000 * 60) );
								}
								catch( System.Threading.ThreadInterruptedException )
								{
									loadPS = true;
									ng.utils.logging.LogWriter.writeLine("Being awaken.");
								}
								catch( System.Exception e)
								{
									ng.utils.logging.LogWriter.writeLine("No KANBAN unhandled exception: " + e);
									return;
								}

							}
							else
							{
								break;
							}
						}
						else
						{
							break;
						}

					}


					this.Replan = false;


					ng.utils.logging.LogWriter.writeLine("About to start ShiftPitches: " + this.LineID );

					if ( this.m_aShiftPitch != null )
					{
						ShiftPitch[] shiftList = new ShiftPitch[m_aShiftPitch.Count];
						m_aShiftPitch.CopyTo(shiftList,0);
						ng.utils.logging.LogWriter.writeLine("Starting ShiftPitches: " + this.LineID );
						foreach( ShiftPitch sp in shiftList )
						{
							this.currentSP = sp;

							ng.utils.logging.LogWriter.writeLine("Current ShiftPitch: " + sp.ShiftStartDate + " thru " +sp.ShiftEndDate + " for " + this.LineID );
							if (this.m_bReplan == false)
							{
								try
								{
									this.lockedDate = sp.ShiftEndDate.Date;
									Pitch firstPitch = sp.GetFirstScheduledPitch();

									ng.utils.logging.LogWriter.writeLine("Checking  First Pitch for Shift: " + this.LineID );


									if ( firstPitch.PitchStartDate > System.DateTime.Now )
									{
										if ( firstPitch.PitchType != PitchType.EXTENDED_SHIFT )
										{
											//only if we have a neg ative cum do I enforce this.
											if ( this.GetCumCountFromStats( null ) < 0 )
											{
												this.EnforceShiftExtension( sp , "BEGIN" );
											}
										}
									}
									//									}
									//									else
									//									{
									//										ng.utils.logging.LogWriter.writeLine("First Pitch is null: " + this.LineID );
									//
									//									}

									sp.Start();

									if  (this.Replan == false )
									{
										this.MoveShiftToHistory( sp );
									}



								}
								catch( System.Threading.ThreadInterruptedException  )
								{
									//loadPS = true;
									ng.utils.logging.LogWriter.writeLine("Shift " + sp.ShiftStartDate + " thru " + sp.ShiftEndDate + " for Line: " +sp.LineID + " has been Interrupted.");
									// possibly a Replan has been received.
								}
								catch (System.Threading.ThreadAbortException)
								{
									return;
								}
							}

						}
					}



					//this.currentSP = null;
					//this.currentPitch = null; // clear value;
					ng.utils.logging.LogWriter.writeLine("Line Pitch Complete");




					// check for data
					// if no data Suspend
					bool gotData = false;

					while( gotData == false )
					{


						System.DateTime nextPitchDay = System.DateTime.Now;
						object nextDay = System.DBNull.Value;

						if ( this.GetPitchCount( System.DateTime.Now , false ) > 0 )
						{
							// this means we have data for today that has not been processed
						}
						else
						{
							// if today is friday or weekend 
							if ( System.DateTime.Today.DayOfWeek == System.DayOfWeek.Friday || System.DateTime.Today.DayOfWeek == System.DayOfWeek.Saturday || System.DateTime.Today.DayOfWeek == System.DayOfWeek.Sunday)
							{
								object nws = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetNextShiftTime( this.line, System.DateTime.Now );

								System.DateTime compareDate = System.DateTime.Now;

								bool loadWeekend = true;
								if ( nws == System.DBNull.Value )
								{
									// make sure that if today is sunday that it is BEFORE noon

									if ( System.DateTime.Today.DayOfWeek == System.DayOfWeek.Sunday )
									{

										compareDate = new System.DateTime(compareDate.Year,compareDate.Month,compareDate.Day,12,0,0);

										if ( System.DateTime.Now > compareDate )
										{
											// it's too late on Sunday
											loadWeekend = false;
										}
									}



								}
								else
								{
									System.DateTime nextStartDate = System.DateTime.Parse(  nws.ToString() );

									if ( System.DateTime.Today.DayOfWeek == System.DayOfWeek.Friday )
									{
										compareDate = compareDate.AddDays(2);
										compareDate = new System.DateTime(compareDate.Year,compareDate.Month,compareDate.Day,12,0,0);								}
									else if ( System.DateTime.Today.DayOfWeek == System.DayOfWeek.Saturday )
									{
										//saturday

										compareDate = compareDate.AddDays(1);
										compareDate = new System.DateTime(compareDate.Year,compareDate.Month,compareDate.Day,12,0,0);
									}
									else
									{
										//sunday

										compareDate = new System.DateTime(compareDate.Year,compareDate.Month,compareDate.Day,12,0,0);
									}


									// So if there is a pitch already in db with a start time less than 12 noon
									// Sunday then we will not create any pitches.
									if ( nextStartDate <= compareDate)
									{
										loadWeekend = false;
									}


								}
								if ( loadWeekend )
								{
									ng.data.requirements.heijunka.HeijunkaLineSetupOptions hls = this.GetLineOptions();

									if ( hls != null )
									{
										if ( hls.OverTimeTolerance != null )
										{
											if( hls.OverTimeTolerance.Qualifies( this.GetMinutesBehind( this.lastPitchCompleted ) ))
											{
												ng.data.requirements.heijunka.HeijunkaManager.getInstance().CreateWeekendPitches( this , hls.Line.MasterShift );
											}
										}
									}
								}
							}


							nextDay = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetNextShiftTime( this.line, System.DateTime.Now );
							nextPitchDay = System.DateTime.Now.AddDays(1); // initiali

							if ( nextDay == System.DBNull.Value )
							{
								// no new data
							}
							else
							{								
								nextPitchDay = System.DateTime.Parse( nextDay.ToString() );
								//this.lockedDate = nextPitchDay.Date;
							}
						}




						try
						{


							lock ( ng.data.requirements.heijunka.HeijunkaManager.getInstance().SyncRoot )
							{
								if (ng.data.requirements.heijunka.HeijunkaManager.getInstance().MonitoringFiles == false && this.GetPitchCount(nextPitchDay ,false ) > 0 )
								{
									gotData = true;


									// only load new data from this point on . . 
									this.Load(false,nextPitchDay);
								}
							}

							if ( gotData == false )
							{
								// determine when the next pitch is and then sleep until that time.
								// If there is absolutely no other data in pitch schedule for this line then Suspend until 
								// new data arrives.  This thread will be woke up by the Manager.

								// right now I'm just gonna sleep for 5 minutes but the correct and
								// most efficient way is to Suspend until new data arrives.
								try
								{
									ng.utils.logging.LogWriter.writeLine("No pitch data will try again later: "+this.LineID);
									System.Threading.Thread.Sleep( 1 * ( 1000 * 60) );
								}
								catch( System.Threading.ThreadInterruptedException )
								{
									//got
									//loadPS = true; // force a kanban re-retrieve
									ng.utils.logging.LogWriter.writeLine("Pitch being interrupted will try for data");
									gotData = true;
								}
								catch( System.Exception e)
								{
									ng.utils.logging.LogWriter.writeLine("Pitch being interrupted, unhandled exception: "+ e);
								}
							}
						}
						catch( System.Threading.ThreadInterruptedException )
						{

							ng.utils.logging.LogWriter.writeLine("Load interrupted.");
						}
						catch( ng.data.requirements.heijunka.PitchDataNeedsReloadingException )
						{
							// 
							ng.utils.logging.LogWriter.writeLine("Need to reload and prepare data " + this.LineID);
							gotData = false;
						}


					}
				}
				catch(System.Threading.ThreadInterruptedException  )
				{
					//loadPS = true; // force a kanban re-retrieve
					ng.utils.logging.LogWriter.writeLine("Line Pitch " + this.LineID + " Interrupted, starting over.");
				}


			}
		}

