					select.Where = ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( "SHIFT_START_DT" ).ToString() + " = " 
						+ ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( ng.utils.DbTypeResolver.DbStringBuilder.DateValue(dt).ToString() ) 
						+ " AND LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.line.ID);
					cmd.CommandText = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);

// 10/27/2003 -- RB
//					cmd.CommandText="SELECT COUNT(*) FROM HEIJUNKA_PITCH_SCHEDULE WHERE " 
//						+ ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( "SHIFT_START_DT" ).ToString() + " = " 
//						+ ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( ng.utils.DbTypeResolver.DbStringBuilder.DateValue(dt).ToString() ) + " AND LINE_ID ='" + this.line.ID + "' ";
				}
				else
				{
					ng.utils.SelectStatement select = new ng.utils.SelectStatement();
					select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_PITCH_SCHEDULE"));
					select.Columns = "COUNT(*)";
					select.Where = ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( "SHIFT_START_DT" ).ToString() + " = " 
						+ ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly( ng.utils.DbTypeResolver.DbStringBuilder.DateValue(dt).ToString() ) 
						+ " AND LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.line.ID)
						+ " AND IN_USE = " + ng.utils.DatabaseUtil.QuoteLiteral("N");;
					cmd.CommandText = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);

//					cmd.CommandText="SELECT COUNT(*) FROM HEIJUNKA_PITCH_SCHEDULE WHERE " 
