		public ArrayList AllPitches
		{
			get 
			{
				// On first dispatch, create the full list
				if (m_allPitches == null)
				{

					m_allPitches = new ArrayList();

					// go thru history first
					if ( this.previousShifts != null )
					{
						lock( this.previousShifts.SyncRoot )
						{
							foreach( ShiftPitch oldSP in this.previousShifts )
							{
								foreach(System.Collections.DictionaryEntry de in oldSP.Pitches)
								{
									m_allPitches.Add(de.Value);
								}

							}
						}
					}

					//m_allPitches = new PitchList(this.m_aShiftPitch);
					foreach(ShiftPitch shiftPitch in m_aShiftPitch)
					{
						foreach(System.Collections.DictionaryEntry de in shiftPitch.Pitches)
						{
							m_allPitches.Add(de.Value);
						}
					}
				}

				return m_allPitches;
			}
		}

