		#region Implementation of IEventManager
		public bool TriggerEvent(string eventName)
		{
			if (eventName == null) 
			{
				foreach(string catalogName in this.EventsCatalog)
				{
					TriggerEvent(catalogName);
				}
			}
			else 
			{
				switch (eventName)
				{
					case "List":
						DispatchList();
						break;

					case "Stats":
						DispatchStats();
						break;

					default:
						return false;
				}
			}
			return true;
		}

		public bool TriggerEvent(ng.events.ISystemEventHandler handler, string eventName, ng.events.EventListenerNotConnectedDelegate notConnectedDelegate)
		{
			if (eventName == null) 
			{
				foreach(string catalogName in this.EventsCatalog)
				{
					return TriggerEvent(handler, catalogName, notConnectedDelegate);
				}
			}
			else 
			{
				switch (eventName)
				{
					case "List":
						// force the list to be built
						this.m_allPitches = null;
						ng.events.DefaultEvent.DispatchSingleDataEvent(this.ServiceName, handler, "List", this.AllPitches, ng.events.EventType.Ordered, notConnectedDelegate);
						ng.events.DefaultEvent.DispatchSingleDataEvent(this.ServiceName, handler, "List", this.AllPitches.IndexOf(this.currentPitch), ng.events.EventType.Ordered, notConnectedDelegate);

						if (this.currentPitch.CurrentDetail is AONonWorkingPitch)
						{
							ng.events.DefaultEvent.DispatchSingleDataEvent(
								this.ServiceName,
								handler,
								"List",
								new ng.clients.ui.ListDataEntry(this.AllPitches.IndexOf(currentPitch), new AOPitchData(currentPitch, (AONonWorkingPitch)currentPitch.CurrentDetail), ng.clients.ui.ListAction.Update),
								ng.events.EventType.Ordered,
								notConnectedDelegate);

						}
						break;

					case "Stats":
						ng.events.DefaultEvent.DispatchSingleDataEvent(this.ServiceName, handler, "Stats", GetStats(), ng.events.EventType.Unordered, notConnectedDelegate);
						break;
				}
			}
			return true;
		}

