		/// <summary>
		/// This is the last scheduled pitch for this shift
		/// </summary>
		/// <returns></returns>
		public Pitch GetLastScheduledPitch()
		{
			int idx = this.pitches.Count;

			if ( idx > 0 )
			{
				Pitch lastPitch = (Pitch) this.pitches.GetByIndex( idx - 1 );
				return lastPitch;
			}
			else
			{
				return null;
			}
