			ng.utils.logging.LogWriter.writeLine("ShiftPitchCount: " + idx + " for " + this.LineID );

			if ( idx > 0 )
			{
				Pitch lastPitch = (Pitch) this.pitches.GetByIndex( 0 );
				return lastPitch;
			}
			else
			{
				return null;
			}
		}

		public void RunPitch(Pitch p )
		{

			p.PitchEvent += new ng.data.requirements.heijunka.PitchDelegate( this.linePitch.OnPitch );
			p.PitchItemEvent += new ng.data.requirements.heijunka.PitchItemDelegate( this.linePitch.OnPitchItem );

			p.Start();

			p.PitchEvent -= new ng.data.requirements.heijunka.PitchDelegate( this.linePitch.OnPitch );
			p.PitchItemEvent -= new ng.data.requirements.heijunka.PitchItemDelegate( this.linePitch.OnPitchItem );

		}

