		{
			if ( _pitch !=null )
			{
				int curPos = this.pitches.IndexOfKey( _pitch.PitchNbr );

				curPos ++;

				if ( curPos >= this.pitches.Count )
				{
					return null;
				}
				else
				{
					ng.data.requirements.heijunka.Pitch np = (ng.data.requirements.heijunka.Pitch) this.pitches.GetByIndex( curPos );

					return np;
				}
			}
			else
			{
				return ( ng.data.requirements.heijunka.Pitch) this.pitches.GetByIndex(0);
			}

		}

