	public class ExtendedShiftPitch : ng.data.requirements.heijunka.Pitch
	{


//		public ExtendedShiftPitch(
//			System.Runtime.Serialization.SerializationInfo info,
//			System.Runtime.Serialization.StreamingContext context) : base( info, context ) {}
//

		public ExtendedShiftPitch(ng.data.requirements.heijunka.ShiftPitch _ShiftPitch,ng.data.requirements.heijunka.AbstractPitchDetail _ap) : base( _ShiftPitch , _ap)  {}

		public static ExtendedShiftPitch CreateNew( System.DateTime _start, System.DateTime _end, ShiftPitch _sp, AbstractPitchDetail _apd)
		{
			ExtendedShiftPitch esp = new ExtendedShiftPitch(_sp,_apd);
			esp.PitchStartDate = _start;
			esp.PitchEndDate = _end;


			// create a working pitch 
			WorkingPitch wp = new WorkingPitch(_apd);

			wp.PitchType = PitchType.EXTENDED_SHIFT;
			wp.PitchStartDate = _start;
			wp.PitchEndDate = _end;
			wp.ShiftStartDate = _start;
			wp.ShiftEndDate = _end;
			wp.PitchNbr = 1 ;

			wp.Row_ID = ng.utils.DatabaseUtil.GetSK("HEIJUNKA_SK");
			esp.RowID = wp.Row_ID;
			esp.PitchType = PitchType.EXTENDED_SHIFT;


			esp.Add( wp );


			wp.Save();


			return esp;


		}



	}

