		public bool IsExtendedShiftRunning(System.DateTime _dateTime)
		{
			long currentRow = this.GetLastPitchRow();

			if ( currentRow > 0 )
			{

				ng.utils.SelectStatement select = new ng.utils.SelectStatement();
				select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_PITCH_SCHEDULE"));
				select.Columns = "SHIFT_START_DT , SHIFT_END_DT";
				select.Where = "LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.LineID) 
					+ " AND ROW_ID = " + currentRow;
				string sql = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);

				// 10/27/2003 -- RB
				//string sql = "SELECT SHIFT_START_DT , SHIFT_END_DT FROM HEIJUNKA_PITCH_SCHEDULE WHERE LINE_ID = '" + this.LineID + "' " + 
				//	" AND ROW_ID = " + currentRow;

				using ( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
				{
					conn.Open();
					System.Data.IDbCommand cmd = conn.CreateCommand();
					cmd.CommandText = sql;

					System.Data.IDataReader rdr = cmd.ExecuteReader();
					bool fallsBetween = false;

					try
					{
						if ( rdr.Read() ) 
						{
							System.DateTime dtStart = (System.DateTime) rdr.GetDateTime( rdr.GetOrdinal("SHIFT_START_DT") );
							System.DateTime dtEnd = (System.DateTime) rdr.GetDateTime( rdr.GetOrdinal("SHIFT_END_DT") );

							if ( _dateTime >= dtStart  && _dateTime <= dtEnd )
							{
								fallsBetween = true;
							}

						}

						return fallsBetween;

					}
					finally
					{
						rdr.Close();
						conn.Close();
					}
				}
			}
			else
			{
				return false;
			}
		}
