		private void MoveShiftToHistory( ShiftPitch sp )
		{

			// null shift name indicates an extended shift.

			if ( this.previousShifts == null )
			{
				this.previousShifts = new System.Collections.ArrayList();
			}


			lock( this.previousShifts.SyncRoot )
			{
				if  (this.previousShifts.Count > 0 )
				{
					System.Collections.ArrayList copyPL = new System.Collections.ArrayList( this.previousShifts );
					foreach( ShiftPitch pSp in copyPL )
					{
						System.TimeSpan diff = System.DateTime.Now.Subtract( pSp.ShiftStartDate );

						if ( diff.TotalHours > 24 )
						{
							pSp.Clear();
							this.previousShifts.Remove( pSp );

						}
					}

				}

				//add shift
				lock ( this.m_aShiftPitch.SyncRoot )
				{
					this.m_aShiftPitch.Remove( sp );
					this.previousShifts.Add( sp );
				}


				// purge old data
				this.PurgeData( 7 );

			}
		}

		private void PurgeData( int daysOld )
		{

			System.DateTime oldDate = System.DateTime.Today.Subtract( new System.TimeSpan( daysOld ,0,0,0,0) );

			string sOldDate = ng.utils.DbTypeResolver.DbStringBuilder.DateValue(oldDate).ToString();

			string sWhere = "LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.LineID)
				+ " AND SHIFT_START_DT < " + sOldDate;
			string sql = ng.utils.sql.SqlSaveBuilder.formatDelete("HEIJUNKA_PITCH_SCHEDULE",sWhere);

			//string sql = "DELETE FROM HEIJUNKA_PITCH_SCHEDULE WHERE LINE_ID = '" + this.LineID + "' AND SHIFT_START_DT < " + sOldDate  ;

			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
			{
				conn.Open();
				System.Data.IDbCommand cmd = conn.CreateCommand();
				cmd.CommandText = sql;
				int rows = cmd.ExecuteNonQuery();
			}

			// purge Production Table

			//sql = "DELETE FROM HEIJUNKA_PROD_SCHEDULE WHERE LINE_ID = '" + this.LineID + "' AND SIGNAL_START_DT < " + sOldDate;

			sWhere = "LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.LineID)
				+ " AND SIGNAL_START_DT < " + sOldDate;

			sql = ng.utils.sql.SqlSaveBuilder.formatDelete("HEIJUNKA_PROD_SCHEDULE",sWhere);
			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
			{
				conn.Open();
				System.Data.IDbCommand cmd = conn.CreateCommand();
				cmd.CommandText = sql;
				int rows = cmd.ExecuteNonQuery();
			}


			System.DateTime forecastDate = System.DateTime.Today.Subtract( new System.TimeSpan( 28 ,0,0,0,0) );
			string sForecastDate = ng.utils.DbTypeResolver.DbStringBuilder.DateValue(forecastDate).ToString();

			sql = "DELETE FROM HEIJUNKA_FORECAST WHERE LINE_ID = '" + this.LineID + "' AND PERIOD_DT < " + sForecastDate;
			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
			{
				conn.Open();
				System.Data.IDbCommand cmd = conn.CreateCommand();
				cmd.CommandText = sql;
				int rows = cmd.ExecuteNonQuery();
			}


		}

		private void Load(IDbConnection conn, bool newDataOnly,object o_date) 
		{


			m_aShiftPitch = null;

			m_aShiftPitch = new ArrayList();

			System.DateTime pitchDay = System.DateTime.Now;
			bool loadForStats = false;
			long currentRow=0;

			if( o_date != null )
			{
				pitchDay = (System.DateTime) o_date;
			}
			else
			{
				currentRow = this.GetLastPitchRow();

				if ( currentRow > 0 )
				{
					if ( this.IsExtendedShiftRunning( pitchDay ))
					{
						// only load for a row for Extend Shift Pitch
						// only load if the current time falls between the extend shift pitch start and end time
						loadForStats = true;
					}
				}
			}



			// temp list of pitches
			System.Collections.ArrayList listOfPitches = new System.Collections.ArrayList();


			IDbCommand cmd = conn.CreateCommand();

			System.Text.StringBuilder sb = new System.Text.StringBuilder();

			System.DateTime today = pitchDay;
			string sToday = ng.utils.DbTypeResolver.DbStringBuilder.DateValue(today).ToString();

			ng.utils.SelectStatement select = new ng.utils.SelectStatement();
			select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_PITCH_SCHEDULE"));
			select.Columns = "HEIJUNKA_PITCH_SCHEDULE.*";

			if ( loadForStats )
			{
				// 10/27/2003 -- RB
				//sb.Append("SELECT HPS.* FROM HEIJUNKA_PITCH_SCHEDULE HPS WHERE " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HPS.SHIFT_START_DT") + " = (SELECT " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HJS.SHIFT_START_DT") + " FROM HEIJUNKA_PITCH_SCHEDULE HJS WHERE HJS.ROW_ID = " + currentRow + " AND HJS.LINE_ID = '"+this.line.ID+"' ) ");
				select.Where = ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HEIJUNKA_PITCH_SCHEDULE.SHIFT_START_DT") + " = (SELECT " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HJS.SHIFT_START_DT") + " FROM HEIJUNKA_PITCH_SCHEDULE HJS WHERE HJS.ROW_ID = " + currentRow + " AND HJS.LINE_ID = " 
					+ ng.utils.DatabaseUtil.QuoteLiteral(this.line.ID)+")";
			}
			else
			{
				select.Where = ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(sToday) 
					+ " IN ( " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HEIJUNKA_PITCH_SCHEDULE.SHIFT_START_DT") + ", " 
					+ ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HEIJUNKA_PITCH_SCHEDULE.SHIFT_END_DT") + ")";
				//sb.Append("SELECT HPS.* FROM HEIJUNKA_PITCH_SCHEDULE HPS WHERE " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly(sToday) + " IN ( " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HPS.SHIFT_START_DT") + ", " + ng.utils.DbTypeResolver.DbStringBuilder.DbDateOnly("HPS.SHIFT_END_DT") + " ) ");
			}

			select.Where += " AND HEIJUNKA_PITCH_SCHEDULE.LINE_ID = " 
				+ ng.utils.DatabaseUtil.QuoteLiteral(this.line.ID);

			//sb.Append(" AND HPS.LINE_ID = '"+this.line.ID+"' ");

			if ( newDataOnly  )
			{
				//sb.Append(" AND HPS.IN_USE = 'N' ");
				select.Where += " AND HEIJUNKA_PITCH_SCHEDULE.IN_USE " 
					+ ng.utils.DatabaseUtil.QuoteLiteral("N");
			}

			//sb.Append(" ORDER BY HPS.SHIFT_START_DT,HPS.SHIFT_END_DT,HPS.PITCH_NBR");
			select.OrderBy = "HEIJUNKA_PITCH_SCHEDULE.SHIFT_START_DT,HEIJUNKA_PITCH_SCHEDULE.SHIFT_END_DT,HEIJUNKA_PITCH_SCHEDULE.PITCH_NBR";

			cmd.CommandText = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);
			System.DateTime tdt;

			ng.utils.logging.LogWriter.writeLine("Load Pitch Detail for Line " + this.LineID );
			ng.utils.logging.LogWriter.writeLine( cmd.CommandText );

			NullableDateTime nonWorkingStartDate;
			NullableDateTime nonWorkingEndDate;
			System.DateTime pitchStart = System.DateTime.Now;
			System.DateTime pitchEnd = System.DateTime.Now;

			string   nonWorkingDesc;

			ng.data.NullableDateTime ndt = null;

			ng.data.requirements.heijunka.AbstractPitchDetail ap = null;
			bool gotData = false;


			IDataReader rdr = cmd.ExecuteReader();
			try
			{



				while (rdr.Read()) 
				{



					gotData =true;
					if (rdr.IsDBNull(rdr.GetOrdinal("NON_WORKING_START_DT")))
					{
						nonWorkingStartDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("NON_WORKING_START_DT") );
						nonWorkingStartDate = new ng.data.NullableDateTime( tdt );
					}

					if (rdr.IsDBNull(rdr.GetOrdinal("NON_WORKING_END_DT")))
					{
						nonWorkingEndDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("NON_WORKING_END_DT") );
						nonWorkingEndDate = new ng.data.NullableDateTime( tdt );

					}

					nonWorkingDesc = DatabaseUtil.readString(rdr,"NON_WORKING_DESC");

					ap = new WorkingPitch();

					if (rdr.IsDBNull(rdr.GetOrdinal("SHIFT_START_DT")))
					{
						ap.ShiftStartDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("SHIFT_START_DT") );
						ap.ShiftStartDate = new ng.data.NullableDateTime( tdt );
					}

					if (rdr.IsDBNull(rdr.GetOrdinal("SHIFT_END_DT")))
					{
						ap.ShiftEndDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("SHIFT_END_DT") );
						ap.ShiftEndDate = new ng.data.NullableDateTime( tdt );

					}


					if (rdr.IsDBNull(rdr.GetOrdinal("PITCH_START_DT")))
					{
						ap.PitchStartDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("PITCH_START_DT") );
						pitchStart = tdt;
						ap.PitchStartDate = new ng.data.NullableDateTime( tdt );
					}

					if (rdr.IsDBNull(rdr.GetOrdinal("PITCH_END_DT")))
					{
						ap.PitchEndDate = new ng.data.NullableDateTime(null);
					}
					else
					{
						tdt = rdr.GetDateTime( rdr.GetOrdinal("PITCH_END_DT") );
						pitchEnd = tdt;
						ap.PitchEndDate = new ng.data.NullableDateTime( tdt );
					}

					ap.DataIndicator  = DatabaseUtil.readString(rdr,"DATA_INDICATOR");
					ap.DivisionIntCode = DatabaseUtil.readString(rdr,"DIVISION_INT_CODE");
					ap.DivisionName    = DatabaseUtil.readString(rdr,"DIVISION_NAME");
					ap.EnterpriseName  = DatabaseUtil.readString(rdr,"ENTERPRISE_NAME");
					ap.InstanceName    = DatabaseUtil.readString(rdr,"INSTANCE_NAME");
					ap.LineID          = DatabaseUtil.readString(rdr,"LINE_ID");
					ap.LineIntCode     = DatabaseUtil.readString(rdr,"LINE_INT_CODE");
					ap.PitchNbr        = DatabaseUtil.readNumber(rdr,"PITCH_NBR");
					ap.Replan		   = DatabaseUtil.readBoolean(rdr,"RE_PLAN");
					ap.SiteIntCode     = DatabaseUtil.readString(rdr,"SITE_INT_CODE");
					ap.Row_ID		   = DatabaseUtil.readNumber(rdr,"ROW_ID");
					ap.ShiftName       = DatabaseUtil.readString(rdr,"SHIFT_NAME"); 
					bool resetCum      = DatabaseUtil.readBoolean(rdr,"RESET_CUM");
					string pitchStatus = DatabaseUtil.readString(rdr,"IN_USE");

					PitchStatus pStatus;


					if ( pitchStatus == null || pitchStatus == "N" )
					{
						pStatus = PitchStatus.NotInUse;
					}
					else if ( pitchStatus == "Y" )
					{
						pStatus = PitchStatus.InUse;
					}
					else
					{
						pStatus = PitchStatus.Completed;
					}


					string pitchType = null;

					if ( rdr.IsDBNull( rdr.GetOrdinal("PITCH_TYPE") ) )
					{
						ap.PitchType = PitchType.NORMAL;

					}
					else
					{
						pitchType   = DatabaseUtil.readString(rdr,"PITCH_TYPE");

						if ( pitchType.ToUpper() == PitchType.EXTENDED_SHIFT.ToString() )
						{
							ap.PitchType = PitchType.EXTENDED_SHIFT;
						}
						else if (  pitchType.ToUpper() == PitchType.OVERTIME.ToString()  )
						{
							ap.PitchType = PitchType.OVERTIME;
						}
						else
						{
							ap.PitchType = PitchType.NORMAL;
						}

					}


					string pitchItemID=null;

					if ( rdr.IsDBNull( rdr.GetOrdinal("PITCH_ITEM_ID")) == false )
					{
						pitchItemID = (string) rdr["PITCH_ITEM_ID"];
					}
					ap.PitchItemID = pitchItemID;

					ap.CumCount		   = DatabaseUtil.readNumber(rdr,"CUM_COUNT");

					if (ap.PitchStartDate > ap.PitchEndDate)
					{
						throw new System.Exception("Received Pitch Row "+ ap.Row_ID +" that has "+
							"start date that is greater than it end date "+ ap.PitchStartDate +"," +ap.PitchEndDate +" for pitch nbr " + ap.PitchNbr);
					}

					//ng.data.requirements.heijunka.LinePitch lP = this.GetLinePitch(ap);
					ng.data.requirements.heijunka.ShiftPitch sP  = this.GetShiftPitch(ap);

					//					if (lP == null)
					//					{
					//						lP = new LinePitch(this,ap);
					//						this.Add(lP);
					//					}
					//					lP.Add(ap);

					if (sP == null)
					{
						//ng.utils.logging.LogWriter.writeLine("Creating a ShiftPitch!: " + this.LineID );
						sP = new ShiftPitch(this,ap);
						this.Add(sP);
					}


					Pitch pitch = null;

					if ( nonWorkingStartDate == null )
					{
						// means this is a work pitch 100%
						pitch = sP.Add(ap);
					}
					else
					{
						// this means that there is non work for this pitch


						System.DateTime non_Start=(System.DateTime) nonWorkingStartDate.Value;
						System.DateTime non_End = (System.DateTime) nonWorkingEndDate.Value;;


						System.TimeSpan timeofPitch = ap.TotalTime;
						System.TimeSpan timeofNonWork = non_End.TimeOfDay - non_Start.TimeOfDay;

						System.TimeSpan timeDiff = timeofPitch - timeofNonWork;

						if ( timeDiff.Minutes < 1 )
						{
							// this means the pitch is 100% non work
							//ng.utils.logging.LogWriter.writeLine("Not adding non work pitch: " + this.LineID );

						}
						else
						{
							//ng.utils.logging.LogWriter.writeLine("Adding non work pitch: " + this.LineID );
							pitch = sP.Add(ap);
							// this means pitch is a combination of work/non work
						}

					}



					if (!(nonWorkingEndDate.isNull && nonWorkingStartDate.isNull))
					{
						if (nonWorkingDesc.Substring(0,2).ToUpper() == "AO")
						{
							ap = new AONonWorkingPitch( ap  );
						}
						else
						{
							ap = new NonWorkingPitch(ap);
						}

						ap.PitchItemID = pitchItemID;

						ap.Row_ID		   = DatabaseUtil.readNumber(rdr,"ROW_ID");

						if (rdr.IsDBNull(rdr.GetOrdinal("NON_WORKING_START_DT")))
						{
							//((NonWorkingPitch)ap).NonWorkingStartDate = new ng.data.NullableDateTime(null);
							ap.PitchStartDate = new ng.data.NullableDateTime(null);
						}
						else
						{
							tdt = rdr.GetDateTime( rdr.GetOrdinal("NON_WORKING_START_DT") );
							//((NonWorkingPitch)ap).NonWorkingStartDate = new ng.data.NullableDateTime( tdt );
							ap.PitchStartDate = tdt;

						}
						if (rdr.IsDBNull(rdr.GetOrdinal("NON_WORKING_END_DT")))
						{
							//((NonWorkingPitch)ap).NonWorkingEndDate = new ng.data.NullableDateTime(null);
							ap.PitchEndDate = new ng.data.NullableDateTime(null);
						}
						else
						{
							tdt = rdr.GetDateTime( rdr.GetOrdinal("NON_WORKING_END_DT") );
							//((NonWorkingPitch)ap).NonWorkingEndDate = new ng.data.NullableDateTime( tdt );
							ap.PitchEndDate = tdt;

						} 

						((NonWorkingPitch)ap).NonWorkingDesc = DatabaseUtil.readString(rdr,"NON_WORKING_DESC");


						//						lP.Add(ap);
						pitch = sP.Add(ap);
					}		

					if ( pitch != null )
					{
						pitch.PitchStartDate = pitchStart;
						pitch.PitchEndDate = pitchEnd;
						pitch.PitchStatus = pStatus;
						pitch.ResetCum = resetCum;
						pitch.RowID = ap.Row_ID;
						listOfPitches.Add( pitch );
					}


				}

			}

			finally  
			{
				rdr.Close();

				if (gotData == false )
				{
					throw new ng.data.requirements.heijunka.NoPitchDataForTodayException("No Heijunka Pitches for Today");
				}

			}


			// prepare data
			try
			{
				ng.utils.logging.LogWriter.writeLine("Preparing pitch data, row count=" + listOfPitches.Count + " for line: " + this.LineID );

				if ( this.PreparePitches( listOfPitches ) == true )
				{
					throw new ng.data.requirements.heijunka.PitchDataNeedsReloadingException("Data needs to be reloaded and prepared.");
				}
				else
				{
					m_allPitches = null;
					DispatchList();
				}
			}
			catch( ng.data.requirements.heijunka.HeijunkaForecastNotFoundException )
			{
				ng.utils.logging.LogWriter.writeLine("No Forecast for Line " + this.LineID );

			}
		}

		private void SetPartsPerPitch( ng.data.requirements.heijunka.Pitch p, ng.data.requirements.heijunka.HeijunkaForecastEntry fce )
		{
			double st_wpp = (double) this.m_iWorkMinutesPerPitch;
			int ppp = 0;
			double  wpp;

			if ( fce == null )
			{
				throw new ng.data.exceptions.ObjectNotFoundException("Could not get a Forecast entry for " + p.ShiftPitch.ShiftEndDate.ToString("d") );
			}

			ppp = fce.PartsPerPitch;

			wpp = (double) System.Math.Ceiling(p.TotalWorkTime.TotalMinutes);

			double q = (double) (wpp / st_wpp);  // rate of a normal

			p.PartsPerPitch = (int) ( ppp * q);
			 //p.CalculatedPartsPerPitch = 
			// get pitch stats

			if ( p.PitchType == PitchType.NORMAL && p.PitchStatus == ng.data.requirements.heijunka.PitchStatus.Completed )
			{
				if ( p.PitchJob != null )
				{
					p.SetCumOffsetStatistics( p.PitchJob.GetMarriedCount() - p.PartsPerPitch );
				}
				else
				{
					p.SetCumOffsetStatistics( 0 - p.PartsPerPitch );
				}
			}
			else if ( p.PitchType == PitchType.EXTENDED_SHIFT )
			{
				p.PartsPerPitch = ppp * 2;
			}


		}
		private bool PreparePitches( System.Collections.ArrayList listOfPitches )
		{
			double st_wpp = (double) this.m_iWorkMinutesPerPitch;
			int ppp = 0;
			//double ppp=0;

			ng.data.requirements.heijunka.HeijunkaForecast hjf = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetForecast( this.LineID );
			ng.data.requirements.heijunka.HeijunkaForecastEntry fce  = hjf.GetForecastEntry( System.DateTime.Now );
			string sCurrDate = null;

			bool rtnVal = false;  // indicates if we changed any data

			foreach( Pitch p in listOfPitches )
			{

				//double  wpp;

				if ( sCurrDate == null || (sCurrDate != p.ShiftPitch.ShiftEndDate.ToString("d") ))
				{
					sCurrDate = p.ShiftPitch.ShiftEndDate.ToString("d");
					fce = hjf.GetForecastEntry( p.ShiftPitch.ShiftEndDate );
					if ( fce == null )
					{
						throw new ng.data.requirements.heijunka.HeijunkaForecastNotFoundException("Could not get a Forecast entry for " + p.ShiftPitch.ShiftEndDate.ToString("d") );
					}

					ppp = fce.PartsPerPitch;
				}

				this.SetPartsPerPitch( p , fce );
				//				wpp = (double) System.Math.Ceiling(p.TotalWorkTime.TotalMinutes);
				//
				//				double q = (double) (wpp / st_wpp);  // rate of a normal
				//
				//				p.PartsPerPitch = (int) System.Math.Ceiling( ppp * q);
				//
				//				// get pitch stats
				//				
				//				if ( p.PitchType == PitchType.NORMAL && p.PitchStatus == ng.data.requirements.heijunka.PitchStatus.Completed )
				//				{
				//					if ( p.PitchJob != null )
				//					{
				//						p.SetCumOffsetStatistics( p.PitchJob.GetMarriedCount() - p.PartsPerPitch );
				//					}
				//					else
				//					{
				//						p.SetCumOffsetStatistics( 0 - p.PartsPerPitch );
				//					}
				//				}
				//				else if ( p.PitchType == PitchType.EXTENDED_SHIFT )
				//				{
				//					p.PartsPerPitch = ppp * 2;
				//				}
				//



				// additional logic KUMAR!!!	

				foreach(System.Collections.DictionaryEntry de in p.PitchDetails)
				{
					ng.data.requirements.heijunka.AbstractPitchDetail apd = (ng.data.requirements.heijunka.AbstractPitchDetail) de.Value;


					if (apd is ng.data.requirements.heijunka.NonWorkingPitch)
					{
						//if apd.EndDate is greater than the Pitches End date than start scanning the pitches AFTER
						// this pitch

						ng.data.requirements.heijunka.NonWorkingPitch origNWP = (ng.data.requirements.heijunka.NonWorkingPitch) apd;

						if (apd.PitchEndDate > p.PitchEndDate)
						{
							string nonWorkDesc = origNWP.NonWorkingDesc;


							int currIdx = listOfPitches.IndexOf( p ) + 1;
							// this scans the next set of pitches
							if ( currIdx < listOfPitches.Count )
							{
								ng.data.requirements.heijunka.Pitch nextP = (ng.data.requirements.heijunka.Pitch) listOfPitches[ currIdx ];

								if ( nextP.PitchEndDate >= apd.PitchEndDate )
								{
									// this means that the non work ends with this pitch
									ng.data.requirements.heijunka.AbstractPitchDetail firstAPD = (ng.data.requirements.heijunka.AbstractPitchDetail)nextP.PitchDetails.GetByIndex(0);

									ng.data.requirements.heijunka.NonWorkingPitch nwp = new NonWorkingPitch( firstAPD );
									nwp.NonWorkingDesc = origNWP.NonWorkingDesc;
									nwp.PitchStartDate = nextP.PitchStartDate;

									nwp.PitchEndDate = apd.PitchEndDate;
									origNWP.PitchEndDate = p.PitchEndDate;

									if ( nextP.PitchDetails.ContainsKey( nwp.PitchEndDate ) == true )
									{
										nextP.PitchDetails.Remove( nwp.PitchEndDate );
									}
									nextP.Add( nwp );

								}
								else
								{
									// this means that this pitch is a 100% consumed with non-work from apd
									// clear the nextP details and add ONE non work. then UPDATE DB.

									// Get first detail item in nextP
									ng.data.requirements.heijunka.AbstractPitchDetail firstAPD = (ng.data.requirements.heijunka.AbstractPitchDetail)nextP.PitchDetails.GetByIndex(0);
									nextP.PitchDetails.Clear();

									ng.data.requirements.heijunka.NonWorkingPitch nwp = new NonWorkingPitch( firstAPD );
									nwp.NonWorkingDesc = origNWP.NonWorkingDesc;
									nwp.PitchStartDate = nextP.PitchStartDate;
									nwp.PitchEndDate = origNWP.PitchEndDate;
									origNWP.PitchEndDate = p.PitchEndDate;


									nextP.Add( nwp );

								}

								p.UpdateNonWork(nonWorkDesc);
								nextP.UpdateNonWork(nonWorkDesc);


								// true means that we changed data and that the pitches need to be reloaded.
								rtnVal = true;
							}
							else
							{
								// this bad data and we will brute force the non work to be the same as the pitch
								// end time
								apd.PitchEndDate = p.PitchEndDate;

							}



						}

					}

				}

			}

			return rtnVal;
		}

