		public void Start()
		{
			this.LoadProductionSchedule();

			// load prior 24 hours for history.
			System.DateTime yest = System.DateTime.Today.Subtract( new System.TimeSpan(1,0,0,0) );
			try
			{
				this.Load( false ,yest );

				// automatically move yesterdays shift into history.

				if ( this.Shifts != null )
				{
					System.Collections.ArrayList shiftCopy = new System.Collections.ArrayList(this.Shifts );

					foreach( ShiftPitch sp in shiftCopy )
					{
						this.MoveShiftToHistory( sp );
					}
				}
			}
			catch( ng.data.exceptions.ObjectNotFoundException )
			{
				// no data for yesterday.
				ng.utils.logging.LogWriter.writeLine("No data found for yesterday: " + this.LineID );
			}


			thread = new System.Threading.Thread( new System.Threading.ThreadStart(Run) );
			thread.Priority = System.Threading.ThreadPriority.Normal;
			thread.Start();
		}
