			//string sql = "SELECT CURRENT_PITCH_ROW FROM HEIJUNKA_LINE_STATS STATS, HEIJUNKA_PITCH_SCHEDULE HJS WHERE STATS.LINE_ID = '" + this.LineID + "' AND STATS.CURRENT_PITCH_ROW = HJS.ROW_ID ";

