			select.Tables.Add( new ng.utils.SqlTable("HEIJUNKA_PITCH_SCHEDULE"
				,ng.utils.SqlJoinType.Inner,"HEIJUNKA_LINE_STATS.CURRENT_PITCH_ROW = HEIJUNKA_PITCH_SCHEDULE.ROW_ID"));
			select.Columns = "CURRENT_PITCH_ROW";
			select.Where = "HEIJUNKA_LINE_STATS.LINE_ID = " + ng.utils.DatabaseUtil.QuoteLiteral(this.LineID);

			string sql = ng.utils.DbTypeResolver.DbStringBuilder.FormatSelect(select);


			using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
