public ng.data.requirements.heijunka.Pitch GetNextPitch( ng.data.requirements.heijunka.Pitch _pitch )
		{
			bool foundSourceShift = false;
			foreach( ng.data.requirements.heijunka.ShiftPitch sp in this.m_aShiftPitch )
			{
				if ( foundSourceShift == false  )
				{
					if ( sp.ContainsPitch( _pitch ) )
					{
						foundSourceShift = true;
						if ( sp.IsLastPitch( _pitch ) == false )
						{
							return sp.GetNextPitch( _pitch );
						}
					}
				}
				else
				{
					// this code being executed indicates that the _pitch was the last pitch of the
					// prior Shift.  Now we simple return this first pitch of this shift.
					if ( sp.Pitches.Count > 0 )
					{
						return sp.GetNextPitch( null );
					}
				}

			}

			return null;
		}

