public bool EnforceShiftExtension( ShiftPitch sp, string mode )
		{
			ng.data.requirements.heijunka.HeijunkaLineSetupOptions hls = this.GetLineOptions();

			if ( hls.ExtendedShiftTolerance != null )
			{
				Pitch fromPitch = null;

				if ( mode == "BEGIN" )
				{
					fromPitch = sp.GetFirstScheduledPitch();
				}
				else
				{
					fromPitch = this.CurrentPitch;
				}
				if ( hls.ExtendedShiftTolerance.Qualifies( this.GetMinutesBehind( fromPitch ) ))
				{
					// extend shift

					System.DateTime extStart ;
					System.DateTime extEnd;

					Pitch cPitch = sp.GetLastScheduledPitch();

					ng.data.requirements.heijunka.ExtendedShiftPitch  esp = null;

					if ( mode == "BEGIN" )
					{
						extStart = System.DateTime.Now;
						extEnd = sp.ShiftStartDate;


						if ( extStart < extEnd )
						{
							esp = ExtendedShiftPitch.CreateNew( extStart , extEnd , sp,(AbstractPitchDetail)sp.GetFirstScheduledPitch().PitchDetails.GetByIndex(0) );


							// Create a dummy shift


							ng.data.requirements.heijunka.ShiftPitch extShift = new ShiftPitch();
							extShift.ShiftName = "Shift Extension";

							extShift.ShiftStartDate = extStart;
							extShift.ShiftEndDate = extEnd;

							extShift.ExtendedShift = true;
							esp.CumCount = this.GetCumCountFromStats(null);
							esp.UpdatePitch();


							ng.data.requirements.heijunka.HeijunkaForecast hjf = ng.data.requirements.heijunka.HeijunkaManager.getInstance().GetForecast( this.LineID );
							ng.data.requirements.heijunka.HeijunkaForecastEntry fce  = hjf.GetForecastEntry( System.DateTime.Now );

							if ( fce != null )
							{
								// set parts per pitch
								esp.PartsPerPitch = fce.PartsPerPitch * 2;
							}


							extShift.Add( esp );

							if ( this.CurrentShiftPitch != null )
							{
								int idx = this.m_aShiftPitch.IndexOf( this.CurrentShiftPitch );
								lock( this.m_aShiftPitch.SyncRoot )
								{
									this.m_aShiftPitch.Insert( idx  , extShift );
								}
							}
							else
							{
								lock( this.m_aShiftPitch.SyncRoot )
								{
									this.m_aShiftPitch.Insert(0, extShift );
								}
							}

							this.m_allPitches = null;
							this.DispatchList();


							sp.RunPitch( esp );
							this.MoveShiftToHistory( extShift );
							return true;
						}

					}


				}
			}

			return false;
		}

