		public void UpdateNonWork(string desc)
		{

			// get the min start date from all non work entries
			// get the max end date from all  non work entries
			object min=null;
			object max=null;
			foreach( System.Collections.DictionaryEntry de in this.pitchDetails )
			{
				ng.data.requirements.heijunka.AbstractPitchDetail apd = (ng.data.requirements.heijunka.AbstractPitchDetail) de.Value;
				if ( apd is ng.data.requirements.heijunka.NonWorkingPitch )
				{
					if ( min == null )
					{
						min = apd.PitchStartDate;
					}
					else
					{
						System.DateTime t_begin = (System.DateTime) min;
						if ( t_begin > apd.PitchStartDate )
						{
							min = apd.PitchStartDate;
						}
					}


					if ( max == null )
					{
						max = apd.PitchEndDate;
					}
					else
					{
						System.DateTime t_end = (System.DateTime) max;
						if ( t_end < apd.PitchEndDate )
						{
							max = apd.PitchEndDate;

						}
					}



				}


			}

			if ( max != null )
			{
				System.DateTime minDT = System.DateTime.Parse( min.ToString() );
				System.DateTime maxDT = System.DateTime.Parse( max.ToString() );

				using( System.Data.IDbConnection conn = ng.utils.DatabaseUtil.getConnection() )
				{
					ng.utils.sql.SqlSaveBuilder oIns = new ng.utils.sql.SqlSaveBuilder();
					oIns.addColumn("NON_WORKING_START_DT",ng.utils.DbTypeResolver.DbStringBuilder.DateValue(minDT));
					oIns.addColumn("NON_WORKING_END_DT",ng.utils.DbTypeResolver.DbStringBuilder.DateValue(maxDT));
					//oIns.addColumn("NON_WORKING_DESC",ng.utils.DatabaseUtil.QuoteLiteral(desc));
					oIns.addColumn("NON_WORKING_DESC",desc);
					string sql = oIns.formatUpdate("HEIJUNKA_PITCH_SCHEDULE","ROW_ID = " + this.RowID);

//					string sql = "UPDATE HEIJUNKA_PITCH_SCHEDULE SET NON_WORKING_START_DT = " + ng.utils.DbTypeResolver.DbStringBuilder.DateValue(minDT) + ", " +
//						" NON_WORKING_END_DT = " + ng.utils.DbTypeResolver.DbStringBuilder.DateValue(maxDT) + ", " +
//						" NON_WORKING_DESC='" + desc + "' WHERE ROW_ID = " + this.RowID;

					conn.Open();
					System.Data.IDbCommand cmd = conn.CreateCommand();
					cmd.CommandText = sql;

					int rows = cmd.ExecuteNonQuery();

					conn.Close();

				}
			}
		}

