		public System.TimeSpan TotalWorkTime
		{
			get
			{

				System.TimeSpan tsDiff = new System.TimeSpan(0,0,0,0,0);
				//long ticks;

				foreach( System.Collections.DictionaryEntry de in this.pitchDetails )
				{
					ng.data.requirements.heijunka.AbstractPitchDetail apd = (ng.data.requirements.heijunka.AbstractPitchDetail) de.Value;
					if ( apd is ng.data.requirements.heijunka.WorkingPitch )
					{

						//tsDiff = tsDiff + (   apd.PitchEndDate.TimeOfDay - apd.PitchStartDate.TimeOfDay);

						if ( apd.PitchEndDate.TimeOfDay < apd.PitchStartDate.TimeOfDay )
						{
							System.TimeSpan eod = new System.TimeSpan(24,0,0);

							tsDiff = tsDiff + ( eod - apd.PitchStartDate.TimeOfDay );
							tsDiff = tsDiff + ( apd.PitchEndDate.TimeOfDay );


						}
						else
						{
							tsDiff = tsDiff + (apd.PitchEndDate.TimeOfDay - apd.PitchStartDate.TimeOfDay);
						}
					}
				}

				return tsDiff;
			}
		}
		public System.TimeSpan WorkTimeRemaining
		{
			get
			{

				System.TimeSpan tsDiff = new System.TimeSpan(0,0,0,0,0);
				//long ticks;

				foreach( System.Collections.DictionaryEntry de in this.pitchDetails )
				{
					ng.data.requirements.heijunka.AbstractPitchDetail apd = (ng.data.requirements.heijunka.AbstractPitchDetail) de.Value;
					if ( apd is ng.data.requirements.heijunka.WorkingPitch )
					{
						if ( System.DateTime.Now >= apd.PitchStartDate && System.DateTime.Now < apd.PitchEndDate )
						{
							tsDiff = tsDiff + (   apd.PitchEndDate.TimeOfDay - System.DateTime.Now.TimeOfDay);

							//ticks = ticks + System.TimeSpan.Compare( System.DateTime.Now.TimeOfDay , apd.PitchEndDate.TimeOfDay );
						}
						else if ( System.DateTime.Now < apd.PitchStartDate )
						{
							tsDiff = tsDiff + (  apd.PitchEndDate.TimeOfDay - apd.PitchStartDate.TimeOfDay);

							//ticks = ticks + System.TimeSpan.Compare( apd.PitchStartDate.TimeOfDay , apd.PitchEndDate.TimeOfDay );
						}
					}
				}

				return tsDiff;
			}
		}

		public System.TimeSpan WorkTimeElapsed
		{
			get
			{

				System.TimeSpan tsDiff = new System.TimeSpan(0,0,0,0,0);
				//long ticks;

				foreach( System.Collections.DictionaryEntry de in this.pitchDetails )
				{
					ng.data.requirements.heijunka.AbstractPitchDetail apd = (ng.data.requirements.heijunka.AbstractPitchDetail) de.Value;
					if ( apd is ng.data.requirements.heijunka.WorkingPitch )
					{
						if ( System.DateTime.Now >= apd.PitchStartDate  )
						{
							if ( System.DateTime.Now >= apd.PitchEndDate )
							{
								// total time of pitchitem has elapsed
								tsDiff = tsDiff + (   apd.PitchEndDate - apd.PitchStartDate);

							}
							else
							{
								tsDiff = tsDiff + (   System.DateTime.Now - apd.PitchStartDate);
							}

						}
					}
				}

				return tsDiff;
			}
		}


