public void Add(ng.data.requirements.heijunka.AbstractPitchDetail ap)
		{
			if (ap is ng.data.requirements.heijunka.WorkingPitch)
			{
				this.PitchDetails.Add(ap.PitchEndDate,ap);
			}
			if (ap is ng.data.requirements.heijunka.NonWorkingPitch)
			{
				if (ap is AONonWorkingPitch)
				{
					this.m_bHasAODetail = true;
				}

				ng.data.requirements.heijunka.NonWorkingPitch nwp =  (ng.data.requirements.heijunka.NonWorkingPitch) ap;

				System.Collections.SortedList copyList = new System.Collections.SortedList(this.PitchDetails);

				if ( copyList.Count > 0 )
				{
					foreach(System.Collections.DictionaryEntry de in copyList)
					{
						AbstractPitchDetail apd = (AbstractPitchDetail) de.Value;
						if (nwp.PitchNbr == apd.PitchNbr)
						{
							if (nwp.PitchStartDate <= apd.PitchStartDate)
							{
								PitchDetails.Remove(apd.PitchEndDate);
								apd.PitchStartDate = nwp.PitchEndDate.AddSeconds(1);

								PitchDetails.Remove( nwp.PitchEndDate );

								PitchDetails.Add(apd.PitchEndDate,apd);
								PitchDetails.Add(nwp.PitchEndDate,ap);
							}
							else if (nwp.PitchStartDate > apd.PitchStartDate && nwp.PitchEndDate < apd.PitchEndDate)
							{
								//System.DateTime PitchTime;
								PitchDetails.Remove(apd.PitchEndDate);
								ng.data.requirements.heijunka.WorkingPitch wp = new WorkingPitch(apd);
								wp.PitchStartDate = nwp.PitchEndDate.AddSeconds(1);
								wp.PitchEndDate   = apd.PitchEndDate;
								PitchDetails.Add(wp.PitchEndDate,wp);

								apd.PitchEndDate = nwp.PitchStartDate.AddSeconds(-1);
								PitchDetails.Remove( nwp.PitchEndDate );

								PitchDetails.Add(apd.PitchEndDate,apd);
								PitchDetails.Add(nwp.PitchEndDate,ap);
							}
							else if(nwp.PitchEndDate >= apd.PitchEndDate)
							{
								PitchDetails.Remove(apd.PitchEndDate);
								apd.PitchEndDate = nwp.PitchStartDate.AddSeconds(-1);

								PitchDetails.Remove( nwp.PitchEndDate );

								PitchDetails.Add(apd.PitchEndDate,apd);
								PitchDetails.Add(nwp.PitchEndDate,ap);
							}
							else
							{
								PitchDetails.Remove(apd.PitchEndDate);
								this.PitchDetails.Add(ap.PitchEndDate,ap);
							}
						}

					}
				}
				else
				{
					PitchDetails.Remove(nwp.PitchEndDate);
					this.PitchDetails.Add(nwp.PitchEndDate,ap);
				}

			}
		}

public void Start()
		{
			System.DateTime currentTime = System.DateTime.Now;
			System.TimeSpan timeInterval;
			//bool inUse=false;

			if (currentTime > this.PitchEndDate)
			{
				// mark this pitch as Complete.
				//this.AdjustCumQuantity( (int) (this.PartsPerPitch - this.CumCount) );

				// if this pitch has not started then we need to account for its Parts Per pitch and adjust the 
				// LinePitch cum.

				if ( this.PitchStatus == ng.data.requirements.heijunka.PitchStatus.Completed)
				{
					// this means that we have already processed this row.
					this.DeletePitch(this);
					return;
				}
				else
				{
					// this means that either the pitch is marked as not in use or in use,but because the time
					// has expired we need to credit the cum with this pitches info.  let it pass thru here.
				}


			}
			else if (currentTime < this.PitchStartDate)
			{
				// ok
				timeInterval = (this.PitchStartDate - currentTime);
				ng.utils.logging.LogWriter.writeLine("Line " + this.ShiftPitch.LineID + ", Pitch doesn't start for " + timeInterval.TotalMinutes + " minutes, sleeping . . . ");
				if ( this.shiftPitch.LinePitch.SleepForPitch( timeInterval ) == false )
				{
					// this means that the line pitch has been interrupted
					return;
				}
				//				System.Threading.Thread.Sleep(timeInterval);
			}
			else if ( currentTime > this.m_dPitchStartDate && currentTime <= this.PitchEndDate )
			{
				// this means were starting a little late and have jump to appropriate pitch detail
			}
			else if ( currentTime >= this.PitchStartDate && currentTime < this.PitchEndDate )
			{
				// this means we are probably starting right on time.
			}
			else
			{
				// not ok
				return;
			}

			if ( this.PitchEvent != null )
			{
				// listeners
				this.PitchEvent( this , "BEGIN" ); 
			}

			//inUse = true;
			if ( this.PitchStatus == ng.data.requirements.heijunka.PitchStatus.NotInUse )
			{
				this.UpdatePitch();
			}

			foreach( System.Collections.DictionaryEntry de in this.pitchDetails )
			{

				AbstractPitchDetail apd = (AbstractPitchDetail) de.Value;


				bool validPitchItem = false;
				if ( apd is WorkingPitch )
				{
					if ( apd.PitchEndDate > currentTime ) validPitchItem = true;
				}
				else
				{
					NonWorkingPitch nwp = ( NonWorkingPitch) apd;
					if ( nwp.PitchEndDate > currentTime ) validPitchItem = true;
				}
				// starting . . .

				this.currentItem = apd;

				if ( validPitchItem )
				{


					this.PitchItemEvent(this,apd,"BEGIN");

					// DOUBLE CHECK TO MAKE SURE THAT NOW IS LESS THAN APD.PITCHENDDATE

					if( System.DateTime.Now < apd.PitchEndDate)
					{
						timeInterval = (apd.PitchEndDate - System.DateTime.Now );
						ng.utils.logging.LogWriter.writeLine("Pitch " + this.m_iPitchNbr + " sleeping for " + timeInterval.TotalMinutes + " Minutes.");
						if ( this.shiftPitch.LinePitch.SleepForPitch( timeInterval ) == false )
						{
							// this means that the line pitch has been interrupted
							return;
						}
					}


					this.PitchItemEvent(this,apd,"END");
				}
				//
			}

			this.currentItem = null;

			if ( this.PitchEvent != null )
			{
				// listeners
				this.PitchEvent( this , "END" );
			}
			this.DeletePitch(this);

		}

